CTA = "Like, comment, share, and subscribe for more Bible stories."
def R(name, picks, ref=("","")):
    src = STORIES[name]; out = []
    for i, t in picks:
        s = dict(src[i]); s["text"] = t; out.append(s)
    oc = [s for s in src if s["draw"] == "outro2"]
    o = dict(oc[-1]) if oc else sc(ref, "outro2", "")
    o["text"] = CTA; out.append(o)
    STORIES[name + "3"] = out

